1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Fixed city-to-region lookup used to derive an owner's {@code locality}.
8	 *
9	 * <p>The table is intentionally closed: only Sydney, Melbourne and Brisbane map to a
10	 * canonical region. Any other (or missing) city derives the locality {@code "UNKNOWN"}.
11	 */
12	public final class CityRegion {
13	
14	    /** City (case-insensitive) -> canonical region. */
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	        "sydney", "NSW",
17	        "melbourne", "VIC",
18	        "brisbane", "QLD");
19	
20	    /** Region -> inclusive {low, high} 4-digit postcode range. */
21	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
22	        "NSW", new int[] {2000, 2099},
23	        "VIC", new int[] {3000, 3099},
24	        "QLD", new int[] {4000, 4099});
25	
26	    /** Locality returned when the city is not in {@link #CITY_REGION}. */
27	    public static final String UNKNOWN = "UNKNOWN";
28	
29	    private CityRegion() {
30	    }
31	
32	    /** The canonical region for {@code city}, or {@code "UNKNOWN"} when it is not in the table. */
33	    public static String localityOf(String city) {
34	        if (city == null) {
35	            return UNKNOWN;
36	        }
37	        return CITY_REGION.getOrDefault(city.trim().toLowerCase(Locale.ROOT), UNKNOWN);
38	    }
39	
40	    /**
41	     * The inclusive {@code {low, high}} postcode range for {@code city}'s region, or {@code null}
42	     * when the city has no known region (in which case any 4-digit postcode is accepted).
43	     */
44	    public static int[] postcodeRangeOf(String city) {
45	        return REGION_POSTCODES.get(localityOf(city));
46	    }
47	}
