1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.regex.Pattern;
6	
7	import net.officefloor.plugin.variable.Out;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
10	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
11	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
12	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
13	import org.springframework.web.bind.annotation.RequestBody;
14	
15	/**
16	 * Binds the owner body and rejects it when any required field is missing or blank, so an
17	 * invalid body is a 400 (listing the offending field names) even when the owner does not exist.
18	 * Also normalizes the telephone to E.164 form (see {@link TelephoneE164}), publishing the
19	 * normalized value so it is stored and returned as {@code telephone}.
20	 * The address is normalized (see {@link AddressNormalizer}) before the required-field check, so a
21	 * value that is blank only after normalization is rejected, and the normalized form is stored and
22	 * returned as {@code address}.
23	 * The optional email is accepted when absent; when present it must be a syntactically valid
24	 * address (else 400) and is lower-cased so it is stored and returned as {@code email}.
25	 * Runs before {@link LoadOwner}/{@link BuildOwner} and publishes the body for later steps.
26	 */
27	public class ValidateOwner {
28	
29	    /** Syntactic email check: a non-empty local part, an '@', then a dotted domain. */
30	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s.]+(\\.[^@\\s.]+)+$");
31	
32	    /** A valid postcode is exactly four digits. */
33	    private static final Pattern POSTCODE = Pattern.compile("^[0-9]{4}$");
34	
35	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
36	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
37	            InvalidPostcodeException {
38	        List<String> missing = new ArrayList<>();
39	        if (isBlank(request.getFirstName())) {
40	            missing.add("firstName");
41	        }
42	        if (isBlank(request.getLastName())) {
43	            missing.add("lastName");
44	        }
45	        // Normalize the address before the required-field check, so an address that is blank
46	        // only after normalization is rejected, and the normalized value is stored and returned.
47	        request.setAddress(AddressNormalizer.normalize(request.getAddress()));
48	        if (isBlank(request.getAddress())) {
49	            missing.add("address");
50	        }
51	        if (isBlank(request.getCity())) {
52	            missing.add("city");
53	        }
54	        if (isBlank(request.getTelephone())) {
55	            missing.add("telephone");
56	        }
57	        if (!missing.isEmpty()) {
58	            throw new MissingOwnerFieldsException(missing);
59	        }
60	        // Normalize telephone to E.164; reject anything that cannot form a valid number.
61	        String e164 = TelephoneE164.normalize(request.getTelephone());
62	        if (e164 == null) {
63	            throw new InvalidTelephoneException(request.getTelephone());
64	        }
65	        request.setTelephone(e164);
66	        // Email is optional. When present it must be syntactically valid; store it lower-cased.
67	        String email = request.getEmail();
68	        if (email != null && !email.isBlank()) {
69	            String normalized = email.trim().toLowerCase();
70	            if (!EMAIL.matcher(normalized).matches()) {
71	                throw new InvalidEmailException(email);
72	            }
73	            request.setEmail(normalized);
74	        }
75	        // Postcode is optional. When present it must be four digits and, when the city maps to a
76	        // known region, fall within that region's range; a city with no known region accepts any
77	        // 4-digit postcode. The (trimmed) value is stored and returned as given.
78	        String postcode = request.getPostcode();
79	        if (postcode != null && !postcode.isBlank()) {
80	            String trimmed = postcode.trim();
81	            if (!POSTCODE.matcher(trimmed).matches()) {
82	                throw new InvalidPostcodeException(postcode);
83	            }
84	            int[] range = CityRegion.postcodeRangeOf(request.getCity());
85	            if (range != null) {
86	                int value = Integer.parseInt(trimmed);
87	                if (value < range[0] || value > range[1]) {
88	                    throw new InvalidPostcodeException(postcode);
89	                }
90	            }
91	            request.setPostcode(trimmed);
92	        }
93	        validated.set(request);
94	    }
95	
96	    private static boolean isBlank(String value) {
97	        return value == null || value.isBlank();
98	    }
99	}
