1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.rest.function.owner.MembershipLevel;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct.
18	 *
19	 * <p>The {@code membershipLevel} is derived from the owner's own fields alone (see
20	 * {@link MembershipLevel}).
21	 */
22	@Mapper(uses = PetMapper.class)
23	public abstract class OwnerMapper {
24	
25	    @Mapping(target = "displayName",
26	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
27	    @Mapping(target = "initials",
28	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
29	    @Mapping(target = "membershipLevel",
30	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.MembershipLevel.of(owner))")
31	    @Mapping(target = "locality",
32	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.CityRegion.localityOf(owner.getCity()))")
33	    @Mapping(target = "contactPreference",
34	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.ContactPreference.of(owner))")
35	    @Mapping(target = "identityKey",
36	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.of(owner))")
37	    @Mapping(target = "bulkSignupWarning", ignore = true)
38	    public abstract OwnerDto toOwnerDto(Owner owner);
39	
40	    public abstract Owner toOwner(OwnerDto ownerDto);
41	
42	    @Mapping(target = "id", ignore = true)
43	    @Mapping(target = "pets", ignore = true)
44	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
45	
46	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
47	
48	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
49	
50	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
51	        OwnerPageDto ownerPageDto = new OwnerPageDto();
52	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
53	        ownerPageDto.setPage(ownerPage.getNumber());
54	        ownerPageDto.setSize(ownerPage.getSize());
55	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
56	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
57	        return ownerPageDto;
58	    }
59	}
